def check_weak_invariant(current_time, ready_tasks, current_matching, priorities):
    for task_b in ready_tasks:
        if task_b not in current_matching.values():
            for processor_j in task_b.affinity_mask:
                assigned_task_i = None
                for task_i, proc in current_matching.items():
                    if proc == processor_j:
                        assigned_task_i = task_i
                        break

                if assigned_task_i is not None:
                    if priorities[assigned_task_i] < priorities[task_b]:
                        return False # Weak invariant violated
    return True # Weak invariant satisfied

def check_strong_invariant(current_time, ready_tasks, current_matching, priorities, reachable_processors_map):
    for task_b in ready_tasks:
        if task_b not in current_matching.values():
            for processor_pi in reachable_processors_map[task_b]: # R_b(t)
                assigned_task_i = None
                for task_i, proc in current_matching.items():
                    if proc == processor_pi:
                        assigned_task_i = task_i
                        break

                if assigned_task_i is not None:
                    if priorities[assigned_task_i] < priorities[task_b]:
                        return False # Strong invariant violated
    return True # Strong invariant satisfied

def is_hierarchical(affinity_masks):
    for i in range(len(affinity_masks)):
        for k in range(i + 1, len(affinity_masks)):
            alpha_i = affinity_masks[i]
            alpha_k = affinity_masks[k]

            is_subset_ik = alpha_i.issubset(alpha_k)
            is_subset_ki = alpha_k.issubset(alpha_i)
            is_disjoint = alpha_i.isdisjoint(alpha_k)

            if not (is_subset_ik or is_subset_ki or is_disjoint):
                return False # Not hierarchical
    return True # Hierarchical

